def has_cycle_of_length(adj, start, length):
    """Check if there's a cycle of given length starting from 'start'"""
    # BFS/DFS to find cycles
    visited = {start: 0}
    stack = [(start, [start])]

    while stack:
        node, path = stack.pop()
        if len(path) == length:
            if start in adj[node]:
                return True
            continue
        for neighbor in adj[node]:
            if neighbor == start and len(path) == length:
                return True
            if neighbor not in visited or visited[neighbor] > len(path):
                visited[neighbor] = len(path)
                stack.append((neighbor, path + [neighbor]))
    return False

def would_create_short_cycle(adj, u, v, max_cycle=6):
    """Check if adding edge (u,v) would create a cycle of length <= max_cycle"""
    # BFS from u to v, find shortest path
    from collections import deque
    dist = {u: 0}
    queue = deque([u])

    while queue:
        node = queue.popleft()
        if dist[node] >= max_cycle:
            continue
        for neighbor in adj[node]:
            if neighbor == v:
                # Path length is dist[node] + 1, cycle length is dist[node] + 2
                cycle_len = dist[node] + 2
                if cycle_len <= max_cycle:
                    return True
            if neighbor not in dist:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return False

